const http = require('http');
const crypto = require('crypto');

// Secure message framing protocol parser
// Frame format: [4-byte type][4-byte length][payload][32-byte HMAC]
const HMAC_KEY = crypto.randomBytes(32);
const MAX_FRAME_SIZE = 65536;
const FRAME_HEADER_SIZE = 8;
const HMAC_SIZE = 32;

class FrameParser {
  constructor() {
    this.buffer = Buffer.alloc(0);
    this.frames = [];
  }

  // Append incoming data
  append(data) {
    this.buffer = Buffer.concat([this.buffer, data]);
  }

  // Validate HMAC of a complete frame
  validateHMAC(frameData, expectedHMAC) {
    const computed = crypto.createHmac('sha256', HMAC_KEY)
      .update(frameData)
      .digest();
    return crypto.timingSafeEqual(computed, expectedHMAC);
  }

  // Calculate total frame size from header fields
  // type(4) + length(4) + payload(length) + hmac(32)
  calculateFrameSize(payloadLength) {
    // Use standard arithmetic (no bitwise truncation)
    const totalSize = FRAME_HEADER_SIZE + payloadLength + HMAC_SIZE;
    return totalSize;
  }

  // Validate that the declared payload length is within bounds
  isValidPayloadLength(payloadLength) {
    // Ensure payload length is within safe integer range and positive
    if (payloadLength <= 0 || payloadLength > MAX_FRAME_SIZE) return false;
    const totalSize = this.calculateFrameSize(payloadLength);
    // Check total frame size doesn't exceed maximum
    if (totalSize > MAX_FRAME_SIZE) return false;
    if (totalSize < FRAME_HEADER_SIZE + HMAC_SIZE) return false;
    return true;
  }

  // Try to parse one frame from the buffer
  parseFrame() {
    if (this.buffer.length < FRAME_HEADER_SIZE) return null;

    const frameType = this.buffer.readUInt32BE(0);
    const payloadLength = this.buffer.readUInt32BE(4);

    // Validate the payload length
    if (!this.isValidPayloadLength(payloadLength)) {
      throw new Error('Invalid payload length');
    }

    const totalSize = this.calculateFrameSize(payloadLength);

    // Wait for complete frame
    if (this.buffer.length < totalSize) return null;

    // Extract frame components
    const payload = this.buffer.slice(FRAME_HEADER_SIZE, FRAME_HEADER_SIZE + payloadLength);
    const frameData = this.buffer.slice(0, FRAME_HEADER_SIZE + payloadLength);
    const hmac = this.buffer.slice(FRAME_HEADER_SIZE + payloadLength, totalSize);

    // Validate HMAC
    if (hmac.length !== HMAC_SIZE || !this.validateHMAC(frameData, hmac)) {
      throw new Error('HMAC validation failed');
    }

    // Advance buffer
    this.buffer = this.buffer.slice(totalSize);

    return { type: frameType, payload: payload };
  }

  // Parse all available frames
  parseAll() {
    const results = [];
    let frame;
    while ((frame = this.parseFrame()) !== null) {
      results.push(frame);
    }
    return results;
  }
}

// Message handler with per-session state
class SessionManager {
  constructor() {
    this.sessions = new Map();
    this.messageStore = [];
  }

  getSession(sessionId) {
    if (!this.sessions.has(sessionId)) {
      this.sessions.set(sessionId, {
        parser: new FrameParser(),
        authenticated: false,
        messageCount: 0
      });
    }
    return this.sessions.get(sessionId);
  }

  processData(sessionId, data) {
    const session = this.getSession(sessionId);
    session.parser.append(data);

    try {
      const frames = session.parser.parseAll();
      const results = [];

      for (const frame of frames) {
        session.messageCount++;
        const msg = this.handleFrame(session, frame);
        if (msg) results.push(msg);
      }

      return { success: true, messages: results };
    } catch (err) {
      // Reset parser on error
      session.parser = new FrameParser();
      return { success: false, error: err.message };
    }
  }

  handleFrame(session, frame) {
    switch (frame.type) {
      case 1: // AUTH frame
        return this.handleAuth(session, frame.payload);
      case 2: // DATA frame
        if (!session.authenticated) return { error: 'Not authenticated' };
        return this.handleData(session, frame.payload);
      case 3: // PING frame
        return { type: 'pong', timestamp: Date.now() };
      default:
        return { error: 'Unknown frame type' };
    }
  }

  handleAuth(session, payload) {
    // Simple token auth
    const token = payload.toString('utf8');
    if (token.length >= 16 && /^[a-zA-Z0-9]+$/.test(token)) {
      session.authenticated = true;
      return { type: 'auth_ok' };
    }
    return { type: 'auth_failed' };
  }

  handleData(session, payload) {
    const message = payload.toString('utf8');
    this.messageStore.push({
      sessionId: session,
      timestamp: Date.now(),
      data: message
    });
    return { type: 'data_ack', length: message.length };
  }
}

const manager = new SessionManager();

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'POST' && url.pathname === '/api/frame') {
    const sessionId = req.headers['x-session-id'];
    if (!sessionId || !/^[a-f0-9]{16}$/.test(sessionId)) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid session ID' }));
      return;
    }

    const chunks = [];
    let totalSize = 0;
    req.on('data', (chunk) => {
      totalSize += chunk.length;
      if (totalSize > MAX_FRAME_SIZE * 2) {
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      const data = Buffer.concat(chunks);
      const result = manager.processData(sessionId, data);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    });
  } else if (req.method === 'GET' && url.pathname === '/api/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', sessions: manager.sessions.size }));
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(3000);
